"""Parsers for catalog.txt, movements.txt and orders.txt."""
import datetime
import re
import sys
from dataclasses import dataclass, field
from decimal import Decimal

# Quantities and prices may have thousands of digits; lift the int<->str limit.
if hasattr(sys, "set_int_max_str_digits"):
    sys.set_int_max_str_digits(0)

TAX_RATES = ("standard", "reduced", "zero")

SKU_RE = re.compile(r"[A-Za-z]{2,4}-[0-9]{3}")
ORDER_ID_RE = re.compile(r"[Ss][Oo]-[0-9]+")
DATE_RE = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2}")
PRICE_RE = re.compile(r"[0-9]+(\.[0-9]{1,2})?")
COUNT_RE = re.compile(r"[0-9]+")
SIGNED_RE = re.compile(r"[+-]?[0-9]+")
_MOVEMENT_RE = re.compile(r"([^ \t]+)[ \t]+([^ \t]+)[ \t]+([^ \t]+)(?:[ \t]+(.*))?", re.S)
_ORDER_RE = re.compile(r"([^ \t]+)[ \t]+([^ \t]+)[ \t]+([^ \t]+)[ \t]+([^ \t]+)")


class ParseError(ValueError):
    """A mistake in one line of a data file."""

    def __init__(self, line, message):
        super().__init__("line %d: %s" % (line, message))
        self.line = line
        self.reason = message


@dataclass
class Product:
    sku: str
    name: str
    price: Decimal
    reorder: int
    tax: str = "standard"


@dataclass
class Movement:
    date: datetime.date
    sku: str
    quantity: int
    note: str = ""
    line: int = field(default=0, compare=False)


@dataclass
class Order:
    id: str
    date: datetime.date
    customer: str
    lines: list
    line: int = field(default=0, compare=False)


def trim(text):
    return text.strip(" \t")


def records(text):
    """Yield (line number, trimmed line) for every line that is not blank or a comment."""
    if text.startswith("﻿"):
        text = text[1:]
    for number, line in enumerate(text.split("\n"), 1):
        if line.endswith("\r"):
            line = line[:-1]
        line = trim(line)
        if line and not line.startswith("#"):
            yield number, line


def parse_date_text(text):
    """Return a date for YYYY-MM-DD text that exists, else None."""
    if not DATE_RE.fullmatch(text):
        return None
    try:
        return datetime.date(int(text[:4]), int(text[5:7]), int(text[8:]))
    except ValueError:
        return None


def parse_sku_text(text):
    """Return the upper-case SKU for text of the right shape, else None."""
    return text.upper() if SKU_RE.fullmatch(text) else None


def parse_order_id_text(text):
    return text.upper() if ORDER_ID_RE.fullmatch(text) else None


def parse_catalog(text):
    catalog = {}
    for number, line in records(text):
        parts = [trim(p) for p in line.split("|")]
        if len(parts) not in (4, 5):
            raise ParseError(number, "expected 4 or 5 fields separated by '|', got %d" % len(parts))
        sku_text, name, price_text, reorder_text = parts[:4]
        tax = parts[4] if len(parts) == 5 else "standard"
        sku = parse_sku_text(sku_text)
        if sku is None:
            raise ParseError(number, "bad SKU %r" % sku_text)
        if sku in catalog:
            raise ParseError(number, "duplicate SKU %r" % sku_text)
        if not name:
            raise ParseError(number, "empty name")
        if not PRICE_RE.fullmatch(price_text):
            raise ParseError(number, "bad price %r" % price_text)
        whole, _, frac = price_text.partition(".")
        price = Decimal("%s.%s" % (whole, frac.ljust(2, "0")))
        if price < Decimal("0.01"):
            raise ParseError(number, "bad price %r" % price_text)
        if not COUNT_RE.fullmatch(reorder_text):
            raise ParseError(number, "bad reorder %r" % reorder_text)
        if not (tax.isascii() and tax.lower() in TAX_RATES):
            raise ParseError(number, "bad tax %r" % tax)
        catalog[sku] = Product(sku, name, price, int(reorder_text), tax.lower())
    return catalog


def counting_order(movements):
    """Movements in the order they count: by date, same-day in file order."""
    return sorted(movements, key=lambda m: m.date)


def first_below_zero(movements):
    """The first movement (in counting order) that takes stock below zero, or None."""
    balance = {}
    for move in counting_order(movements):
        balance[move.sku] = balance.get(move.sku, 0) + move.quantity
        if balance[move.sku] < 0:
            return move
    return None


def parse_movements(text, catalog):
    moves = []
    for number, line in records(text):
        match = _MOVEMENT_RE.fullmatch(line)
        if not match:
            raise ParseError(number, "expected DATE SKU QUANTITY [NOTE]")
        date_text, sku_text, qty_text, note = match.groups()
        date = parse_date_text(date_text)
        if date is None:
            raise ParseError(number, "bad date %r" % date_text)
        sku = parse_sku_text(sku_text)
        if sku is None:
            raise ParseError(number, "bad SKU %r" % sku_text)
        if sku not in catalog:
            raise ParseError(number, "unknown SKU %r" % sku_text)
        if not SIGNED_RE.fullmatch(qty_text) or int(qty_text) == 0:
            raise ParseError(number, "bad quantity %r" % qty_text)
        moves.append(Movement(date, sku, int(qty_text), trim(note or ""), number))
    bad = first_below_zero(moves)
    if bad is not None:
        raise ParseError(bad.line, "stock of %s would go below zero on %s" % (bad.sku, bad.date))
    return moves


def parse_orders(text, catalog):
    orders = []
    seen = set()
    for number, line in records(text):
        match = _ORDER_RE.fullmatch(line)
        if not match:
            raise ParseError(number, "expected ORDER DATE CUSTOMER LINES")
        id_text, date_text, customer, lines_text = match.groups()
        order_id = parse_order_id_text(id_text)
        if order_id is None:
            raise ParseError(number, "bad order number %r" % id_text)
        if order_id in seen:
            raise ParseError(number, "duplicate order %r" % id_text)
        date = parse_date_text(date_text)
        if date is None:
            raise ParseError(number, "bad date %r" % date_text)
        lines = []
        skus = set()
        for item in lines_text.split(","):
            sku_text, star, qty_text = item.partition("*")
            sku = parse_sku_text(sku_text)
            if not star or sku is None:
                raise ParseError(number, "bad order line %r" % item)
            if sku not in catalog:
                raise ParseError(number, "unknown SKU %r" % sku_text)
            if sku in skus:
                raise ParseError(number, "SKU %r appears twice" % sku_text)
            if not COUNT_RE.fullmatch(qty_text) or int(qty_text) < 1:
                raise ParseError(number, "bad quantity %r" % qty_text)
            skus.add(sku)
            lines.append((sku, int(qty_text)))
        seen.add(order_id)
        orders.append(Order(order_id, date, customer, lines, number))
    return orders
"""The `stockroom` command."""
import csv
import io
import json
import os
import re
import sys

from . import orders as orders_mod
from . import shelves
from .parsing import (COUNT_RE, Movement, ParseError, parse_catalog, parse_date_text,
                      parse_movements, parse_order_id_text, parse_orders, parse_sku_text,
                      first_below_zero)
from .pricing import price_order

# command -> (min args, max args, options it accepts)
COMMANDS = {
    "stock": (0, 0, ("--json",)),
    "low": (0, 0, ("--json",)),
    "history": (1, 1, ("--json",)),
    "quote": (1, 1, ("--json",)),
    "invoice": (1, 1, ("--json",)),
    "report": (0, 0, ("--format",)),
    "receive": (3, 4, ()),
    "ship": (3, 4, ()),
    "fulfil": (2, 2, ()),
}
LITERAL = ("receive", "ship", "fulfil")
NEEDS = {
    "stock": ("movements",), "low": ("movements",), "history": ("movements",),
    "receive": ("movements",), "ship": ("movements",),
    "quote": ("orders",), "fulfil": ("movements", "orders"),
    "invoice": ("movements", "orders"), "report": ("movements", "orders"),
}
FILES = {"catalog": "catalog.txt", "movements": "movements.txt", "orders": "orders.txt"}
USAGE = ("usage: stockroom [--dir DIR] stock|low|history SKU|receive DATE SKU QTY [NOTE]|"
         "ship DATE SKU QTY [NOTE]|quote ORDER|fulfil ORDER DATE|invoice ORDER|report "
         "[--json] [--format text|csv|json]")


class CliError(Exception):
    def __init__(self, code, message):
        super().__init__(message)
        self.code = code


def parse_command_line(args):
    """Return (command, positional args, options, directory); exit-2 errors only."""
    command, positional, options, directory = None, [], {}, "."
    i = 0
    while i < len(args):
        arg = args[i]
        i += 1
        if arg == "--dir":
            if i >= len(args):
                raise CliError(2, "option --dir needs a value")
            directory, i = args[i], i + 1
        elif arg.startswith("--dir="):
            directory = arg[len("--dir="):]
        elif command in LITERAL:
            positional.append(arg)
        elif len(arg) > 1 and arg.startswith("-"):
            name, eq, value = arg.partition("=")
            if name == "--json" and not eq:
                options["--json"] = True
            elif name == "--format" and arg.startswith("--") and eq:
                options["--format"] = value
            elif arg == "--format":
                if i >= len(args):
                    raise CliError(2, "option --format needs a value")
                options["--format"], i = args[i], i + 1
            else:
                raise CliError(2, "unknown option %s" % arg)
        elif command is None:
            command = arg
        else:
            positional.append(arg)
    if command is None:
        raise CliError(2, "no command given\n" + USAGE)
    if command not in COMMANDS:
        raise CliError(2, "unknown command %r\n%s" % (command, USAGE))
    low, high, accepted = COMMANDS[command]
    for name in options:
        if name not in accepted:
            raise CliError(2, "%s does not take %s" % (command, name))
    if options.get("--format", "text") not in ("text", "csv", "json"):
        raise CliError(2, "bad --format value %r (use text, csv or json)" % options["--format"])
    if not low <= len(positional) <= high:
        raise CliError(2, "wrong number of arguments for %s" % command)
    date_arg = {"receive": 0, "ship": 0, "fulfil": 1}.get(command)
    if date_arg is not None and parse_date_text(positional[date_arg]) is None:
        raise CliError(2, "bad date %r (use an existing YYYY-MM-DD)" % positional[date_arg])
    for arg in positional:
        try:
            arg.encode("utf-8")
        except UnicodeEncodeError:
            raise CliError(2, "argument is not valid UTF-8")
    return command, positional, options, directory


def read_text(directory, key, required):
    name = FILES[key]
    try:
        with open(os.path.join(directory, name), "rb") as handle:
            data = handle.read()
    except FileNotFoundError:
        if required:
            raise CliError(2, "%s: no such file" % name)
        return ""
    except OSError as error:
        raise CliError(2, "%s: %s" % (name, error.strerror or error))
    try:
        return data.decode("utf-8")
    except UnicodeDecodeError:
        raise CliError(2, "%s: not valid UTF-8" % name)


def parse_file(key, parser, text, *extra):
    try:
        return parser(text, *extra)
    except ParseError as error:
        raise CliError(1, "%s: %s" % (FILES[key], error))


def emit_json(value):
    return json.dumps(value, indent=2, ensure_ascii=False) + "\n"


def lines_out(lines):
    return "".join(line + "\n" for line in lines)


def append_movements(directory, lines):
    """Append movement lines to movements.txt in one write, adding a missing newline first."""
    path = os.path.join(directory, FILES["movements"])
    try:
        with open(path, "a+b") as handle:
            handle.seek(0, os.SEEK_END)
            prefix = b""
            if handle.tell():
                handle.seek(-1, os.SEEK_END)
                if handle.read(1) != b"\n":
                    prefix = b"\n"
            handle.write(prefix + lines_out(lines).encode("utf-8"))
    except OSError as error:
        raise CliError(2, "%s: %s" % (FILES["movements"], error.strerror or error))


def find_order(orders, arg):
    wanted = parse_order_id_text(arg)
    for order in orders:
        if order.id == wanted:
            return order
    raise CliError(1, "no such order %r" % arg)


def quote_data(quote):
    return {
        "order": quote.order, "date": quote.date.isoformat(), "customer": quote.customer,
        "lines": [{"sku": l.sku, "quantity": l.quantity, "unit": str(l.unit), "gross": str(l.gross),
                   "discount": str(l.discount), "net": str(l.net)} for l in quote.lines],
        "subtotal": str(quote.subtotal), "order_discount": str(quote.order_discount),
        "tax": str(quote.tax), "total": str(quote.total),
    }


def quote_text(quote, prefix=""):
    out = ["%s%s %s %s" % (prefix, quote.order, quote.date.isoformat(), quote.customer)]
    for l in quote.lines:
        out.append("%s %d %s %s %s %s" % (l.sku, l.quantity, l.unit, l.gross, l.discount, l.net))
    out += ["subtotal %s" % quote.subtotal, "order discount %s" % quote.order_discount,
            "tax %s" % quote.tax, "total %s" % quote.total]
    return lines_out(out)


def cmd_stock(catalog, moves, as_json):
    levels = shelves.stock_levels(catalog, moves)
    rows = [(sku, catalog[sku].name, levels[sku], shelves.status(levels[sku], catalog[sku].reorder))
            for sku in sorted(catalog)]
    if as_json:
        return emit_json([{"sku": s, "name": n, "onhand": o, "status": st} for s, n, o, st in rows])
    return lines_out("%s %d %s %s" % (s, o, st, n) for s, n, o, st in rows)


def cmd_low(catalog, moves, as_json):
    items = shelves.low_items(catalog, shelves.stock_levels(catalog, moves))
    if as_json:
        return emit_json([{"sku": s, "onhand": o, "reorder": r, "buy": b} for s, o, r, b in items])
    return lines_out("%s %d %d %d" % item for item in items)


def cmd_history(catalog, moves, arg, as_json):
    sku = parse_sku_text(arg)
    if sku not in catalog:
        raise CliError(1, "unknown SKU %r" % arg)
    rows = shelves.history(sku, moves)
    if as_json:
        return emit_json([{"date": m.date.isoformat(), "delta": shelves.format_delta(m.quantity),
                           "balance": b, "note": m.note} for m, b in rows])
    return lines_out("%s %s %d%s" % (m.date.isoformat(), shelves.format_delta(m.quantity), b,
                                     " " + m.note if m.note else "") for m, b in rows)


def cmd_move(command, directory, catalog, moves, text, args):
    date_text, sku_text, qty_text = args[:3]
    note = args[3].strip(" \t") if len(args) == 4 else ""
    sku = parse_sku_text(sku_text)
    if sku not in catalog:
        raise CliError(1, "unknown SKU %r" % sku_text)
    if not COUNT_RE.fullmatch(qty_text) or int(qty_text) < 1:
        raise CliError(1, "bad quantity %r (use a whole number of one or more)" % qty_text)
    if "\n" in note or "\r" in note:
        raise CliError(1, "a note may not contain a line break")
    quantity = int(qty_text) if command == "receive" else -int(qty_text)
    move = Movement(parse_date_text(date_text), sku, quantity, note)
    bad = first_below_zero(moves + [move])
    if bad is not None:
        raise CliError(1, "%s: %s would take %s below zero on %s" %
                       (FILES["movements"], command, bad.sku, bad.date))
    line = "%s %s %s%s" % (date_text, sku, shelves.format_delta(quantity), " " + note if note else "")
    append_movements(directory, [line])
    return lines_out([line])


def cmd_quote(catalog, orders, arg, as_json):
    quote = price_order(find_order(orders, arg), catalog)
    return emit_json(quote_data(quote)) if as_json else quote_text(quote)


def cmd_invoice(catalog, moves, orders, arg, as_json):
    quote = orders_mod.invoice_quote(find_order(orders, arg), catalog, moves)
    if quote is None:
        raise CliError(1, "nothing has shipped for order %s" % parse_order_id_text(arg))
    return emit_json(quote_data(quote)) if as_json else quote_text(quote, "invoice ")


def cmd_fulfil(directory, moves, orders, args):
    order = find_order(orders, args[0])
    date_text = args[1]
    date = parse_date_text(date_text)
    if date < order.date:
        raise CliError(1, "cannot fulfil %s on %s: before the order date %s" %
                       (order.id, date_text, order.date))
    plan = orders_mod.plan_fulfil(order, date, moves)
    new = [Movement(date, sku, -ship, orders_mod.order_note(order)) for sku, ship, _ in plan if ship > 0]
    if new:
        append_movements(directory, ["%s %s -%d %s" % (date_text, m.sku, -m.quantity, m.note) for m in new])
    sent = orders_mod.shipped_so_far(order, moves + new)
    out = ["%s shipped %d backordered %d" % item for item in plan]
    out.append("status %s" % orders_mod.order_status(order, sent))
    return lines_out(out)


def cmd_report(catalog, moves, orders, fmt):
    rows = orders_mod.report_rows(orders, catalog, moves)
    keys = ["order", "date", "customer", "status", "ordered", "shipped", "quoted", "invoiced"]
    if fmt == "json":
        return emit_json([dict(r, quoted=str(r["quoted"]), invoiced=str(r["invoiced"])) for r in rows])
    if fmt == "csv":
        buffer = io.StringIO()
        writer = csv.writer(buffer, lineterminator="\n")
        writer.writerow(keys)
        for r in rows:
            writer.writerow([r[k] for k in keys])
        return buffer.getvalue()
    return lines_out("%s %s %s %s %d/%d %s %s" % (r["order"], r["date"], r["customer"], r["status"],
                                                  r["shipped"], r["ordered"], r["quoted"], r["invoiced"])
                     for r in rows)


def run(args):
    command, positional, options, directory = parse_command_line(args)
    if not os.path.isdir(directory):
        raise CliError(2, "%s: no such directory" % directory)
    catalog_text = read_text(directory, "catalog", True)
    texts = {key: read_text(directory, key, False) for key in NEEDS[command]}
    catalog = parse_file("catalog", parse_catalog, catalog_text)
    moves = parse_file("movements", parse_movements, texts["movements"], catalog) if "movements" in texts else []
    orders = parse_file("orders", parse_orders, texts["orders"], catalog) if "orders" in texts else []
    as_json = "--json" in options
    if command == "stock":
        return cmd_stock(catalog, moves, as_json)
    if command == "low":
        return cmd_low(catalog, moves, as_json)
    if command == "history":
        return cmd_history(catalog, moves, positional[0], as_json)
    if command in ("receive", "ship"):
        return cmd_move(command, directory, catalog, moves, texts["movements"], positional)
    if command == "quote":
        return cmd_quote(catalog, orders, positional[0], as_json)
    if command == "invoice":
        return cmd_invoice(catalog, moves, orders, positional[0], as_json)
    if command == "fulfil":
        return cmd_fulfil(directory, moves, orders, positional)
    return cmd_report(catalog, moves, orders, options.get("--format", "text"))


def main(argv=None):
    args = sys.argv[1:] if argv is None else list(argv)
    try:
        output = run(args)
    except CliError as error:
        try:
            sys.stderr.write("stockroom: %s\n" % error)
            sys.stderr.flush()
        except (OSError, ValueError):
            pass
        return error.code
    try:
        sys.stdout.buffer.write(output.encode("utf-8"))
        sys.stdout.buffer.flush()
    except BrokenPipeError:
        try:
            os.dup2(os.open(os.devnull, os.O_WRONLY), sys.stdout.fileno())
        except (OSError, ValueError):
            pass
        return 0
    except (OSError, ValueError) as error:
        try:
            sys.stderr.write("stockroom: cannot write output: %s\n" % error)
        except (OSError, ValueError):
            pass
        return 2
    return 0


if __name__ == "__main__":
    sys.exit(main())

"""Parsers for catalog.txt, movements.txt and orders.txt."""
import datetime
import re
import sys
from dataclasses import dataclass, field
from decimal import Decimal

# Quantities and prices may have thousands of digits; lift the int<->str limit.
if hasattr(sys, "set_int_max_str_digits"):
    sys.set_int_max_str_digits(0)

TAX_RATES = ("standard", "reduced", "zero")

SKU_RE = re.compile(r"[A-Za-z]{2,4}-[0-9]{3}")
ORDER_ID_RE = re.compile(r"[Ss][Oo]-[0-9]+")
DATE_RE = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2}")
PRICE_RE = re.compile(r"[0-9]+(\.[0-9]{1,2})?")
COUNT_RE = re.compile(r"[0-9]+")
SIGNED_RE = re.compile(r"[+-]?[0-9]+")
_MOVEMENT_RE = re.compile(r"([^ \t]+)[ \t]+([^ \t]+)[ \t]+([^ \t]+)(?:[ \t]+(.*))?", re.S)
_ORDER_RE = re.compile(r"([^ \t]+)[ \t]+([^ \t]+)[ \t]+([^ \t]+)[ \t]+([^ \t]+)")


class ParseError(ValueError):
    """A mistake in one line of a data file."""

    def __init__(self, line, message):
        super().__init__("line %d: %s" % (line, message))
        self.line = line
        self.reason = message


@dataclass
class Product:
    sku: str
    name: str
    price: Decimal
    reorder: int
    tax: str = "standard"


@dataclass
class Movement:
    date: datetime.date
    sku: str
    quantity: int
    note: str = ""
    line: int = field(default=0, compare=False)


@dataclass
class Order:
    id: str
    date: datetime.date
    customer: str
    lines: list
    line: int = field(default=0, compare=False)


def trim(text):
    return text.strip(" \t")


def records(text):
    """Yield (line number, trimmed line) for every line that is not blank or a comment."""
    if text.startswith("﻿"):
        text = text[1:]
    for number, line in enumerate(text.split("\n"), 1):
        if line.endswith("\r"):
            line = line[:-1]
        line = trim(line)
        if line and not line.startswith("#"):
            yield number, line


def parse_date_text(text):
    """Return a date for YYYY-MM-DD text that exists, else None."""
    if not DATE_RE.fullmatch(text):
        return None
    try:
        return datetime.date(int(text[:4]), int(text[5:7]), int(text[8:]))
    except ValueError:
        return None


def parse_sku_text(text):
    """Return the upper-case SKU for text of the right shape, else None."""
    return text.upper() if SKU_RE.fullmatch(text) else None


def parse_order_id_text(text):
    return text.upper() if ORDER_ID_RE.fullmatch(text) else None


def parse_catalog(text):
    catalog = {}
    for number, line in records(text):
        parts = [trim(p) for p in line.split("|")]
        if len(parts) not in (4, 5):
            raise ParseError(number, "expected 4 or 5 fields separated by '|', got %d" % len(parts))
        sku_text, name, price_text, reorder_text = parts[:4]
        tax = parts[4] if len(parts) == 5 else "standard"
        sku = parse_sku_text(sku_text)
        if sku is None:
            raise ParseError(number, "bad SKU %r" % sku_text)
        if sku in catalog:
            raise ParseError(number, "duplicate SKU %r" % sku_text)
        if not name:
            raise ParseError(number, "empty name")
        if not PRICE_RE.fullmatch(price_text):
            raise ParseError(number, "bad price %r" % price_text)
        whole, _, frac = price_text.partition(".")
        price = Decimal("%s.%s" % (whole, frac.ljust(2, "0")))
        if price < Decimal("0.01"):
            raise ParseError(number, "bad price %r" % price_text)
        if not COUNT_RE.fullmatch(reorder_text):
            raise ParseError(number, "bad reorder %r" % reorder_text)
        if not (tax.isascii() and tax.lower() in TAX_RATES):
            raise ParseError(number, "bad tax %r" % tax)
        catalog[sku] = Product(sku, name, price, int(reorder_text), tax.lower())
    return catalog


def counting_order(movements):
    """Movements in the order they count: by date, same-day in file order."""
    return sorted(movements, key=lambda m: m.date)


def first_below_zero(movements):
    """The first movement (in counting order) that takes stock below zero, or None."""
    balance = {}
    for move in counting_order(movements):
        balance[move.sku] = balance.get(move.sku, 0) + move.quantity
        if balance[move.sku] < 0:
            return move
    return None


def parse_movements(text, catalog):
    moves = []
    for number, line in records(text):
        match = _MOVEMENT_RE.fullmatch(line)
        if not match:
            raise ParseError(number, "expected DATE SKU QUANTITY [NOTE]")
        date_text, sku_text, qty_text, note = match.groups()
        date = parse_date_text(date_text)
        if date is None:
            raise ParseError(number, "bad date %r" % date_text)
        sku = parse_sku_text(sku_text)
        if sku is None:
            raise ParseError(number, "bad SKU %r" % sku_text)
        if sku not in catalog:
            raise ParseError(number, "unknown SKU %r" % sku_text)
        if not SIGNED_RE.fullmatch(qty_text) or int(qty_text) == 0:
            raise ParseError(number, "bad quantity %r" % qty_text)
        moves.append(Movement(date, sku, int(qty_text), trim(note or ""), number))
    bad = first_below_zero(moves)
    if bad is not None:
        raise ParseError(bad.line, "stock of %s would go below zero on %s" % (bad.sku, bad.date))
    return moves


def parse_orders(text, catalog):
    orders = []
    seen = set()
    for number, line in records(text):
        match = _ORDER_RE.fullmatch(line)
        if not match:
            raise ParseError(number, "expected ORDER DATE CUSTOMER LINES")
        id_text, date_text, customer, lines_text = match.groups()
        order_id = parse_order_id_text(id_text)
        if order_id is None:
            raise ParseError(number, "bad order number %r" % id_text)
        if order_id in seen:
            raise ParseError(number, "duplicate order %r" % id_text)
        date = parse_date_text(date_text)
        if date is None:
            raise ParseError(number, "bad date %r" % date_text)
        lines = []
        skus = set()
        for item in lines_text.split(","):
            sku_text, star, qty_text = item.partition("*")
            sku = parse_sku_text(sku_text)
            if not star or sku is None:
                raise ParseError(number, "bad order line %r" % item)
            if sku not in catalog:
                raise ParseError(number, "unknown SKU %r" % sku_text)
            if sku in skus:
                raise ParseError(number, "SKU %r appears twice" % sku_text)
            if not COUNT_RE.fullmatch(qty_text) or int(qty_text) < 1:
                raise ParseError(number, "bad quantity %r" % qty_text)
            skus.add(sku)
            lines.append((sku, int(qty_text)))
        seen.add(order_id)
        orders.append(Order(order_id, date, customer, lines, number))
    return orders
"""The `stockroom` command."""
import csv
import io
import json
import os
import re
import sys

from . import orders as orders_mod
from . import shelves
from .parsing import (COUNT_RE, Movement, ParseError, parse_catalog, parse_date_text,
                      parse_movements, parse_order_id_text, parse_orders, parse_sku_text,
                      first_below_zero)
from .pricing import price_order

# command -> (min args, max args, options it accepts)
COMMANDS = {
    "stock": (0, 0, ("--json",)),
    "low": (0, 0, ("--json",)),
    "history": (1, 1, ("--json",)),
    "quote": (1, 1, ("--json",)),
    "invoice": (1, 1, ("--json",)),
    "report": (0, 0, ("--format",)),
    "receive": (3, 4, ()),
    "ship": (3, 4, ()),
    "fulfil": (2, 2, ()),
}
LITERAL = ("receive", "ship", "fulfil")
NEEDS = {
    "stock": ("movements",), "low": ("movements",), "history": ("movements",),
    "receive": ("movements",), "ship": ("movements",),
    "quote": ("orders",), "fulfil": ("movements", "orders"),
    "invoice": ("movements", "orders"), "report": ("movements", "orders"),
}
FILES = {"catalog": "catalog.txt", "movements": "movements.txt", "orders": "orders.txt"}
USAGE = ("usage: stockroom [--dir DIR] stock|low|history SKU|receive DATE SKU QTY [NOTE]|"
         "ship DATE SKU QTY [NOTE]|quote ORDER|fulfil ORDER DATE|invoice ORDER|report "
         "[--json] [--format text|csv|json]")


class CliError(Exception):
    def __init__(self, code, message):
        super().__init__(message)
        self.code = code


def parse_command_line(args):
    """Return (command, positional args, options, directory); exit-2 errors only."""
    command, positional, options, directory = None, [], {}, "."
    i = 0
    while i < len(args):
        arg = args[i]
        i += 1
        if arg == "--dir":
            if i >= len(args):
                raise CliError(2, "option --dir needs a value")
            directory, i = args[i], i + 1
        elif arg.startswith("--dir="):
            directory = arg[len("--dir="):]
        elif command in LITERAL:
            positional.append(arg)
        elif len(arg) > 1 and arg.startswith("-"):
            name, eq, value = arg.partition("=")
            if name == "--json" and not eq:
                options["--json"] = True
            elif name == "--format" and arg.startswith("--") and eq:
                options["--format"] = value
            elif arg == "--format":
                if i >= len(args):
                    raise CliError(2, "option --format needs a value")
                options["--format"], i = args[i], i + 1
            else:
                raise CliError(2, "unknown option %s" % arg)
        elif command is None:
            command = arg
        else:
            positional.append(arg)
    if command is None:
        raise CliError(2, "no command given\n" + USAGE)
    if command not in COMMANDS:
        raise CliError(2, "unknown command %r\n%s" % (command, USAGE))
    low, high, accepted = COMMANDS[command]
    for name in options:
        if name not in accepted:
            raise CliError(2, "%s does not take %s" % (command, name))
    if options.get("--format", "text") not in ("text", "csv", "json"):
        raise CliError(2, "bad --format value %r (use text, csv or json)" % options["--format"])
    if not low <= len(positional) <= high:
        raise CliError(2, "wrong number of arguments for %s" % command)
    date_arg = {"receive": 0, "ship": 0, "fulfil": 1}.get(command)
    if date_arg is not None and parse_date_text(positional[date_arg]) is None:
        raise CliError(2, "bad date %r (use an existing YYYY-MM-DD)" % positional[date_arg])
    for arg in positional:
        try:
            arg.encode("utf-8")
        except UnicodeEncodeError:
            raise CliError(2, "argument is not valid UTF-8")
    return command, positional, options, directory


def read_text(directory, key, required):
    name = FILES[key]
    try:
        with open(os.path.join(directory, name), "rb") as handle:
            data = handle.read()
    except FileNotFoundError:
        if required:
            raise CliError(2, "%s: no such file" % name)
        return ""
    except OSError as error:
        raise CliError(2, "%s: %s" % (name, error.strerror or error))
    try:
        return data.decode("utf-8")
    except UnicodeDecodeError:
        raise CliError(2, "%s: not valid UTF-8" % name)


def parse_file(key, parser, text, *extra):
    try:
        return parser(text, *extra)
    except ParseError as error:
        raise CliError(1, "%s: %s" % (FILES[key], error))


def emit_json(value):
    return json.dumps(value, indent=2, ensure_ascii=False) + "\n"


def lines_out(lines):
    return "".join(line + "\n" for line in lines)


def append_movements(directory, lines):
    """Append movement lines to movements.txt in one write, adding a missing newline first."""
    path = os.path.join(directory, FILES["movements"])
    try:
        with open(path, "a+b") as handle:
            handle.seek(0, os.SEEK_END)
            prefix = b""
            if handle.tell():
                handle.seek(-1, os.SEEK_END)
                if handle.read(1) != b"\n":
                    prefix = b"\n"
            handle.write(prefix + lines_out(lines).encode("utf-8"))
    except OSError as error:
        raise CliError(2, "%s: %s" % (FILES["movements"], error.strerror or error))


def find_order(orders, arg):
    wanted = parse_order_id_text(arg)
    for order in orders:
        if order.id == wanted:
            return order
    raise CliError(1, "no such order %r" % arg)


def quote_data(quote):
    return {
        "order": quote.order, "date": quote.date.isoformat(), "customer": quote.customer,
        "lines": [{"sku": l.sku, "quantity": l.quantity, "unit": str(l.unit), "gross": str(l.gross),
                   "discount": str(l.discount), "net": str(l.net)} for l in quote.lines],
        "subtotal": str(quote.subtotal), "order_discount": str(quote.order_discount),
        "tax": str(quote.tax), "total": str(quote.total),
    }


def quote_text(quote, prefix=""):
    out = ["%s%s %s %s" % (prefix, quote.order, quote.date.isoformat(), quote.customer)]
    for l in quote.lines:
        out.append("%s %d %s %s %s %s" % (l.sku, l.quantity, l.unit, l.gross, l.discount, l.net))
    out += ["subtotal %s" % quote.subtotal, "order discount %s" % quote.order_discount,
            "tax %s" % quote.tax, "total %s" % quote.total]
    return lines_out(out)


def cmd_stock(catalog, moves, as_json):
    levels = shelves.stock_levels(catalog, moves)
    rows = [(sku, catalog[sku].name, levels[sku], shelves.status(levels[sku], catalog[sku].reorder))
            for sku in sorted(catalog)]
    if as_json:
        return emit_json([{"sku": s, "name": n, "onhand": o, "status": st} for s, n, o, st in rows])
    return lines_out("%s %d %s %s" % (s, o, st, n) for s, n, o, st in rows)


def cmd_low(catalog, moves, as_json):
    items = shelves.low_items(catalog, shelves.stock_levels(catalog, moves))
    if as_json:
        return emit_json([{"sku": s, "onhand": o, "reorder": r, "buy": b} for s, o, r, b in items])
    return lines_out("%s %d %d %d" % item for item in items)


def cmd_history(catalog, moves, arg, as_json):
    sku = parse_sku_text(arg)
    if sku not in catalog:
        raise CliError(1, "unknown SKU %r" % arg)
    rows = shelves.history(sku, moves)
    if as_json:
        return emit_json([{"date": m.date.isoformat(), "delta": shelves.format_delta(m.quantity),
                           "balance": b, "note": m.note} for m, b in rows])
    return lines_out("%s %s %d%s" % (m.date.isoformat(), shelves.format_delta(m.quantity), b,
                                     " " + m.note if m.note else "") for m, b in rows)


def cmd_move(command, directory, catalog, moves, text, args):
    date_text, sku_text, qty_text = args[:3]
    note = args[3].strip(" \t") if len(args) == 4 else ""
    sku = parse_sku_text(sku_text)
    if sku not in catalog:
        raise CliError(1, "unknown SKU %r" % sku_text)
    if not COUNT_RE.fullmatch(qty_text) or int(qty_text) < 1:
        raise CliError(1, "bad quantity %r (use a whole number of one or more)" % qty_text)
    if "\n" in note or "\r" in note:
        raise CliError(1, "a note may not contain a line break")
    quantity = int(qty_text) if command == "receive" else -int(qty_text)
    move = Movement(parse_date_text(date_text), sku, quantity, note)
    bad = first_below_zero(moves + [move])
    if bad is not None:
        raise CliError(1, "%s: %s would take %s below zero on %s" %
                       (FILES["movements"], command, bad.sku, bad.date))
    line = "%s %s %s%s" % (date_text, sku, shelves.format_delta(quantity), " " + note if note else "")
    append_movements(directory, [line])
    return lines_out([line])


def cmd_quote(catalog, orders, arg, as_json):
    quote = price_order(find_order(orders, arg), catalog)
    return emit_json(quote_data(quote)) if as_json else quote_text(quote)


def cmd_invoice(catalog, moves, orders, arg, as_json):
    quote = orders_mod.invoice_quote(find_order(orders, arg), catalog, moves)
    if quote is None:
        raise CliError(1, "nothing has shipped for order %s" % parse_order_id_text(arg))
    return emit_json(quote_data(quote)) if as_json else quote_text(quote, "invoice ")


def cmd_fulfil(directory, moves, orders, args):
    order = find_order(orders, args[0])
    date_text = args[1]
    date = parse_date_text(date_text)
    if date < order.date:
        raise CliError(1, "cannot fulfil %s on %s: before the order date %s" %
                       (order.id, date_text, order.date))
    plan = orders_mod.plan_fulfil(order, date, moves)
    new = [Movement(date, sku, -ship, orders_mod.order_note(order)) for sku, ship, _ in plan if ship > 0]
    if new:
        append_movements(directory, ["%s %s -%d %s" % (date_text, m.sku, -m.quantity, m.note) for m in new])
    sent = orders_mod.shipped_so_far(order, moves + new)
    out = ["%s shipped %d backordered %d" % item for item in plan]
    out.append("status %s" % orders_mod.order_status(order, sent))
    return lines_out(out)


def cmd_report(catalog, moves, orders, fmt):
    rows = orders_mod.report_rows(orders, catalog, moves)
    keys = ["order", "date", "customer", "status", "ordered", "shipped", "quoted", "invoiced"]
    if fmt == "json":
        return emit_json([dict(r, quoted=str(r["quoted"]), invoiced=str(r["invoiced"])) for r in rows])
    if fmt == "csv":
        buffer = io.StringIO()
        writer = csv.writer(buffer, lineterminator="\n")
        writer.writerow(keys)
        for r in rows:
            writer.writerow([r[k] for k in keys])
        return buffer.getvalue()
    return lines_out("%s %s %s %s %d/%d %s %s" % (r["order"], r["date"], r["customer"], r["status"],
                                                  r["shipped"], r["ordered"], r["quoted"], r["invoiced"])
                     for r in rows)


def run(args):
    command, positional, options, directory = parse_command_line(args)
    if not os.path.isdir(directory):
        raise CliError(2, "%s: no such directory" % directory)
    catalog_text = read_text(directory, "catalog", True)
    texts = {key: read_text(directory, key, False) for key in NEEDS[command]}
    catalog = parse_file("catalog", parse_catalog, catalog_text)
    moves = parse_file("movements", parse_movements, texts["movements"], catalog) if "movements" in texts else []
    orders = parse_file("orders", parse_orders, texts["orders"], catalog) if "orders" in texts else []
    as_json = "--json" in options
    if command == "stock":
        return cmd_stock(catalog, moves, as_json)
    if command == "low":
        return cmd_low(catalog, moves, as_json)
    if command == "history":
        return cmd_history(catalog, moves, positional[0], as_json)
    if command in ("receive", "ship"):
        return cmd_move(command, directory, catalog, moves, texts["movements"], positional)
    if command == "quote":
        return cmd_quote(catalog, orders, positional[0], as_json)
    if command == "invoice":
        return cmd_invoice(catalog, moves, orders, positional[0], as_json)
    if command == "fulfil":
        return cmd_fulfil(directory, moves, orders, positional)
    return cmd_report(catalog, moves, orders, options.get("--format", "text"))


def main(argv=None):
    args = sys.argv[1:] if argv is None else list(argv)
    try:
        output = run(args)
    except CliError as error:
        try:
            sys.stderr.write("stockroom: %s\n" % error)
            sys.stderr.flush()
        except (OSError, ValueError):
            pass
        return error.code
    try:
        sys.stdout.buffer.write(output.encode("utf-8"))
        sys.stdout.buffer.flush()
    except BrokenPipeError:
        try:
            os.dup2(os.open(os.devnull, os.O_WRONLY), sys.stdout.fileno())
        except (OSError, ValueError):
            pass
        return 0
    except (OSError, ValueError) as error:
        try:
            sys.stderr.write("stockroom: cannot write output: %s\n" % error)
        except (OSError, ValueError):
            pass
        return 2
    return 0


if __name__ == "__main__":
    sys.exit(main())

